def t(lang: str, key: str, **kwargs) -> str:
    text = T.get(lang, T["en"]).get(key, T["en"].get(key, key))
    return text.format(**kwargs) if kwargs else text

def language_buttons():
    return [(f"{flag} {name}", f"lang:{code}") for code, (flag, name) in LANGUAGES.items()]

def detect_language(telegram_language_code: str | None) -> str:
    code = (telegram_language_code or "").lower()
    if code.startswith("vi"): return "vi"
    if code.startswith("hi"): return "hi"
    if code.startswith("id"): return "id"
    if code.startswith("zh"): return "zh"
    return "en"
